:root {
  --bg: #0f1115;
  --surface: #1a1d24;
  --surface-2: #232733;
  --border: #2e333f;
  --text: #e6e8ec;
  --muted: #9aa2b1;
  --accent: #5b8def;
  --danger: #e5484d;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.app { max-width: 860px; margin: 0 auto; padding: 24px 16px 64px; }

.app-header h1 { margin: 0 0 4px; font-size: 1.8rem; }
.tagline { margin: 0 0 20px; color: var(--muted); }

/* Add form */
.add-form { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; margin-bottom: 20px; }
.add-row { display: flex; gap: 8px; }
.add-row.secondary { margin-top: 8px; }
.add-row input { flex: 1; }
input, select, textarea {
  background: var(--surface-2); color: var(--text); border: 1px solid var(--border);
  border-radius: 8px; padding: 10px 12px; font-size: 0.95rem; width: 100%;
}
input:focus, select:focus, textarea:focus { outline: 2px solid var(--accent); outline-offset: 0; }

button {
  background: var(--surface-2); color: var(--text); border: 1px solid var(--border);
  border-radius: 8px; padding: 10px 16px; font-size: 0.95rem; cursor: pointer;
}
button:hover { border-color: var(--accent); }
button.primary, #add-submit { background: var(--accent); border-color: var(--accent); color: #fff; font-weight: 600; }
button.danger { color: var(--danger); border-color: var(--danger); }

.error-msg { color: var(--danger); margin: 10px 0 0; font-size: 0.9rem; }

/* Controls */
.controls { display: flex; gap: 8px; margin-bottom: 16px; }
