  assert.equal(tagged.bookmarks.length, 1);
  assert.equal(tagged.bookmarks[0].id, b.id);

  // Tags endpoint.
  const tags = await (await fetch(`${base}/api/tags`)).json();
  assert.deepEqual(tags.tags.sort(), ['blog', 'news']);
});

